// Pegar os top 5 trending topics
return $input.all().slice(0, 5).map(item => ({
  json: {
    trending_topic: item.json.title,
    searches: item.json['ht:approx_traffic'] || item.json.approx_traffic || 'N/A',
    link: item.json.link || ''
  }
}));

function extractPauta(obj){
  if(obj==null) return null;
  const cands=[obj, obj.choices&&obj.choices[0]&&obj.choices[0].message&&obj.choices[0].message.content, obj.message&&obj.message.content, obj.content, obj.output, obj.text];
  for(let c of cands){
    if(c==null) continue;
    if(typeof c==='string'){ try{ c=JSON.parse(c.replace(/```json|```/g,'').trim()); }catch(e){ continue; } }
    if(c&&typeof c==='object'&&('relevante' in c||'titulo' in c)) return c;
  }
  return null;
}
const trends=$('Top 5 Trends').all();
const inputs=$input.all();
const results=[];
for(let i=0;i<inputs.length;i++){
  const pauta=extractPauta(inputs[i].json);
  if(pauta&&pauta.relevante!==false&&pauta.titulo){
    results.push({json:{pauta, trending_topic:(trends[i]&&trends[i].json.trending_topic)||''}});
  }
}
return results;
